async function init(){applyLanguage();try{state.config=await api("/api/bootstrap");if(state.config.server_time)state.offset=state.config.server_time-Math.floor(Date.now()/1000);$("demo-actions").hidden=!state.config.demo;$("demo-banner").hidden=!state.config.demo;$("telegram-login").href=safeUrl(state.config.bot_url);applyLanguage();const params=new URLSearchParams(location.hash.slice(1));const token=params.get("token");if(token){history.replaceState(null,"","/");$("login-status").textContent=t("در حال ورود امن…","Signing you in…");const result=await api("/api/auth/exchange","POST",{token});state.csrf=result.csrf;$("login-status").textContent="";}const route=location.hash.slice(1);if(["dashboard","mining","missions","referrals","leaderboard","account","social","admin"].includes(route))state.route=route;await refresh();}catch(error){showLogin();if(error.code!=="login_required")$("login-status").textContent=errorText(error);}}
window.addEventListener("hashchange",()=>{if(state.me)navigate(location.hash.slice(1)).catch(error=>toast(errorText(error),true));});
setInterval(()=>{if(state.me&&!$("modal").open&&!document.hidden)refresh().catch(()=>{});},60000);

function tehranClock() {
 return `<span class="tehran-clock" data-tehran-clock></span>`;
}
function updatePhaseTwoClocks() {
 const stamp=new Intl.DateTimeFormat(state.lang==="fa"?"fa-IR":"en-GB",{dateStyle:"medium",timeStyle:"medium",timeZone:"Asia/Tehran"}).format(new Date(now()*1000));
 document.querySelectorAll("[data-tehran-clock]").forEach(node=>node.textContent=`${stamp} · ${t("تهران","Tehran")}`);
 const cycle=state.me?.mining?.cycle;
 if(cycle) {
  const wait=Math.max(0,cycle.ends_at-now());
  document.querySelectorAll("[data-mining-timer]").forEach(node=>node.textContent=wait?`${n(Math.floor(wait/3600))}:${String(Math.floor(wait%3600/60)).padStart(2,"0")}:${String(wait%60).padStart(2,"0")}`:t("آماده دریافت","Ready to collect"));
  document.querySelectorAll('[data-action="mining-claim"]').forEach(node=>node.disabled=wait>0||state.me.paused);
  document.querySelectorAll("[data-mining-progress]").forEach(node=>node.value=Math.min(28800,Math.max(0,now()-cycle.started_at)));
 }
}
const tierMark=id=>({bronze:"🥉",silver:"🥈",gold:"🥇",platinum:"💠",diamond:"💎"}[id]||"✦");
function miningCard(compact=false) {
 const m=state.me.mining;if(!m)return "";
 const cycle=m.cycle,level=m.level,wait=cycle?Math.max(0,cycle.ends_at-now()):0;
 const gated=state.me.referrals<state.me.required_referrals||!/^0x[a-fA-F0-9]{40}$/.test(state.me.wallet||"");
 const disabled=state.me.paused||!state.me.registered||gated||(!cycle&&(!m.enabled||m.budget_remaining<level.reward));
 return `<article class="card mining-card tier-${e(level.id)} ${cycle?"is-mining":""}"><div class="card-top"><div><span class="eyebrow dark">PRS MINING · PHASE 02</span><h2>${e(t("ماین PRS","Mine PRS"))}</h2></div><span class="tier-badge">${tierMark(level.id)} ${e(field(level,"name"))}</span></div><div class="mining-layout"><div><div class="mining-amount number">${n(cycle?cycle.reward:level.reward)} <small>PRS / ${e(t("۸ ساعت","8 hours"))}</small></div><p>${e(cycle?t("دوره فعال است؛ می‌توانی سایت را ببندی.","Your cycle is active. You can close the website."):t("یک دوره شروع کن؛ بعد از ۸ ساعت پاداش را دریافت کن.","Start a cycle and collect your reward after 8 hours."))}</p>${cycle?`<div class="mining-timer number" data-mining-timer>${e(wait?t("در حال ماین…","Mining…"):t("آماده دریافت","Ready to collect"))}</div><progress data-mining-progress max="28800" value="${Math.min(28800,Math.max(0,now()-cycle.started_at))}"></progress><p class="muted">${e(t("پایان دوره به وقت تهران: ","Cycle ends in Tehran time: ")+date(cycle.ends_at,true))}</p>`:`<p class="switch-hint">${e(!m.enabled?t("شروع دوره جدید موقتاً متوقف است.","New cycles are temporarily paused."):m.budget_remaining<level.reward?t("ظرفیت دوره‌های جدید تکمیل شده است.","New-cycle capacity has been reached."):t("پاداش زمان‌دار داخل پنل؛ بدون نیاز به بازماندن صفحه.","Timed portal rewards. No need to keep this page open."))}</p>`}</div><div class="mining-actions">${gated?`<p class="notice red">${e(t("برای ماین: ۳ دعوت معتبر و ثبت کیف پول لازم است. عضویت کانال نیز الزامی است.","Mining requires 3 verified referrals, a saved wallet and channel membership."))}</p>`:""}<button class="btn primary" data-action="${cycle?"mining-claim":"mining-start"}" ${disabled||(cycle&&wait>0)?"disabled":""}>${icon(cycle?"gift":"clock")}${e(cycle?t("دریافت پاداش","Collect reward"):t("شروع ماین ۸ساعته","Start 8-hour cycle"))}</button>${compact?`<button class="btn ghost" data-action="navigate" data-route="mining">${e(t("سطح من و قوانین ماین","My level & mining rules"))}</button>`:""}</div></div></article>`;
}
function renderMining() {
 const m=state.me.mining,level=m.level,next=level.next;
 return `${heading("YOUR MINING JOURNEY",t("ماین و سطح حساب","Mining & account level"),t("دعوت معتبر و موجودی ذخیره‌شده، سطح تو را تعیین می‌کنند.","Verified referrals and your stored balance determine your level."))}${miningCard()}<div class="split-grid account-section"><article class="card"><h2>${tierMark(level.id)} ${e(t("سطح فعلی: ","Current level: ")+field(level,"name"))}</h2><div class="detail-line"><span>${e(t("موجودی ذخیره‌شده","Stored balance"))}</span><strong>${n(level.stored_balance)} PRS</strong></div><div class="detail-line"><span>${e(t("دعوت‌های تأییدشده","Verified referrals"))}</span><strong>${n(state.me.referrals)}</strong></div><div class="detail-line"><span>${e(t("مجموع ماین دریافت‌شده","Mining rewards collected"))}</span><strong>${n(m.total_claimed)} PRS</strong></div>${next?`<h3 class="account-section">${e(t("تا سطح ","Next level: ")+field(next,"name"))}</h3><p>${e(t("هر دو شرط باید کامل شود.","Both requirements must be met."))}</p><div class="progress-label"><span>${e(t("دعوت معتبر","Verified referrals"))}</span><strong>${n(Math.min(state.me.referrals,next.referrals))} / ${n(next.referrals)}</strong></div><progress max="${next.referrals}" value="${Math.min(state.me.referrals,next.referrals)}"></progress><div class="progress-label"><span>${e(t("موجودی ذخیره‌شده","Stored balance"))}</span><strong>${n(Math.min(level.stored_balance,next.balance))} / ${n(next.balance)}</strong></div><progress max="${next.balance}" value="${Math.min(level.stored_balance,next.balance)}"></progress>`:`<p class="positive-text account-section">${e(t("به بالاترین سطح رسیده‌ای.","You have reached the highest level."))}</p>`}</article><article class="card"><h2>${e(t("قوانین ماین","How mining works"))}</h2><ol class="mining-rules"><li>${e(t("هر دوره ۸ ساعت است؛ پس از دریافت باید دوره بعد را خودت شروع کنی.","Each cycle lasts 8 hours. Collect it, then manually start the next cycle."))}</li><li>${e(t("بعد از پایان دوره، پاداش بیشتر جمع نمی‌شود.","Rewards stop accumulating when the cycle ends."))}</li><li>${e(t("پاداش هر دوره با سطح هنگام شروع ثابت می‌شود.","The reward is fixed using your level when the cycle starts."))}</li><li>${e(t("بعد از پرداخت موفق برداشت، سطح با موجودی باقی‌مانده محاسبه می‌شود؛ درخواست ردشده سطح را کم نمی‌کند.","After a completed payment, your level uses the remaining balance. Rejected requests do not lower it."))}</li><li>${e(t("این ماین پاداش داخل پنل است؛ از پردازنده گوشی استفاده نمی‌کند.","Mining earns portal rewards without using your phone's processor."))}</li></ol></article></div><article class="card account-section"><h2>${e(t("سطح‌ها و پاداش هر دوره","Levels & cycle rewards"))}</h2><div class="table-wrap"><table><thead><tr><th>${e(t("سطح","Level"))}</th><th>${e(t("دعوت لازم","Referrals"))}</th><th>${e(t("موجودی لازم","Stored balance"))}</th><th>${e(t("هر ۸ ساعت","Per 8 hours"))}</th></tr></thead><tbody>${m.tiers.map(tier=>`<tr class="${tier.id===level.id?"me":""}"><td>${tierMark(tier.id)} ${e(field(tier,"name"))}</td><td>${n(tier.referrals)}</td><td>${n(tier.balance)} PRS</td><td>${n(tier.reward)} PRS</td></tr>`).join("")}</tbody></table></div></article>`;
}
const adminActionLabel=action=>({campaign_controls:t("تنظیمات کمپین","Campaign controls"),bonus:t("پاداش دستی","Manual reward"),suspend:t("تعلیق حساب","Account suspension"),resume:t("رفع تعلیق","Account restored"),unlock_wallet:t("فرصت اصلاح کیف پول","Wallet edit unlocked"),update_wallet:t("اصلاح کیف پول","Wallet updated"),create_mission:t("ساخت مأموریت","Mission created"),mission_active:t("وضعیت مأموریت","Mission status"),archive_mission:t("حذف مأموریت از فهرست","Mission archived"),restore_mission:t("بازگردانی مأموریت","Mission restored"),review_submission:t("بررسی مدرک","Submission reviewed"),review_payment:t("بررسی پرداخت","Payment reviewed"),reply_ticket:t("پاسخ پشتیبانی","Support reply")}[action]||action);
function renderMissionArchive(missions) {
 if(!missions.length)return "";
 return `<details class="card admin-section"><summary>${e(t("بایگانی مأموریت‌ها","Archived missions"))} (${n(missions.length)})</summary><p class="switch-hint">${e(t("سوابق پاسخ‌ها و پاداش‌ها نگهداری می‌شوند. بازگردانی، مأموریت را به‌صورت غیرفعال برمی‌گرداند.","Answers and rewards are retained. Restored missions remain inactive until you activate them."))}</p>${missions.map(m=>`<div class="admin-row"><div><h3>${e(field(m,"title"))}</h3><p>${e(t("تکمیل‌شده: ","Completed: "))}${n(m.completed)} · ${n(m.spent)} PRS</p></div><button class="btn ghost small" data-action="restore-mission" data-id="${e(m.id)}">${e(t("بازگردانی","Restore"))}</button></div>`).join("")}</details>`;
}
function archiveMissionModal(id) {
 const mission=state.admin.missions.find(m=>m.id===id);if(!mission)return;
 modal(t("حذف مأموریت از فهرست","Remove mission from list"),`<h3>${e(field(mission,"title"))}</h3><p class="modal-summary">${e(t("این مأموریت از فهرست کاربران حذف و در بایگانی مدیریت نگهداری می‌شود. سوابق پاسخ‌ها و پاداش‌ها باقی می‌مانند و می‌توانی آن را بازگردانی کنی.","This mission will be removed from users' lists and kept in the admin archive. Answers and rewards are preserved, and you can restore it."))}</p>${mission.pending?`<p class="notice">${e(t("مدارک در انتظار بررسی همچنان قابل بررسی و پرداخت خواهند بود.","Pending submissions will remain available for review and rewards."))}</p>`:""}<form data-form="archive-mission" data-id="${e(id)}"><div class="modal-footer"><button class="btn primary" type="submit">${e(t("حذف از فهرست","Remove from list"))}</button><button class="btn ghost" type="button" data-action="close-modal">${e(t("انصراف","Cancel"))}</button></div></form>`);
}
function renderTelegramCheck() {
 const check=state.telegramCheck;
 const result=check?`<div class="${check.ok?"notice":"form-feedback is-error"}" role="status"><p>${e(check.ok?t("اتصال تلگرام و دسترسی مدیریت کانال تأیید شد.","Telegram connection and channel admin access are verified."):errorText({code:check.error}))}</p>${check.bot_username?`<p>${e(t("ربات متصل: @","Connected bot: @"))}${e(check.bot_username)}</p>`:""}<p>${e(t("ربات تنظیم‌شده: @","Configured bot: @"))}${e(check.configured_bot_username)} · ${e(check.channel)}</p>${check.user_is_member===false?`<p>${e(t("حساب مدیر در کانال عضو نیست؛ برای دریافت پاداش ابتدا عضو شو.","Your admin account is not a channel member. Join before claiming user rewards."))}</p>`:""}</div>`:"";
 return `<article class="card admin-section"><div class="section-heading"><h2>${e(t("بررسی اتصال تلگرام و عضویت","Telegram & membership check"))}</h2><button class="btn ghost small" data-action="telegram-check">${e(t("بررسی اتصال","Check connection"))}</button></div><p class="switch-hint">${e(t("پس از تغییر توکن، اتصال سرویس سایت و ادمین‌بودن همان ربات در کانال را بررسی کن.","After changing a token, check the website connection and that the same bot is a channel administrator."))}</p>${result}</article>`;
}
function renderAdmin() {
 const a=state.admin;if(!a)return `<div class="loading">${e(t("در حال دریافت مدیریت…","Loading management…"))}</div>`;
 const tab=state.adminTab||"overview";
 const tabs=`<nav class="admin-tabs" aria-label="${e(t("بخش‌های مدیریت","Management sections"))}">${[["overview",t("کنترل و آمار","Controls & stats")],["users",t("کاربران","Users")],["eligible",t("واجدین شرایط","Eligible users")],["work",t("مأموریت و درخواست‌ها","Missions & requests")],["audit",t("سوابق مدیریت","Admin history")]].map(([key,label])=>`<button class="btn ${tab===key?"primary":"ghost"}" data-action="admin-tab" data-tab="${key}" ${tab===key?'aria-current="page"':""}>${e(label)}</button>`).join("")}</nav>`;
 if(tab==="work")return tabs+renderAdminLegacy();
 let body="";
 if(tab==="users"||tab==="eligible") {
  const eligible=tab==="eligible";
  const page=state.userPage||a.user_page;
  body=eligible ? `<article class="card"><h2>${e(t("کاربران واجد شرایط برداشت","Users eligible to withdraw"))}</h2><p class="switch-hint">${e(t("حداقل ۳ دعوت تأییدشده، کیف پول BNB معتبر، موجودی قابل برداشت حداقل ۲۰٬۰۰۰ PRS و حساب فعال.","At least 3 confirmed referrals, a valid BNB wallet, at least 20,000 PRS available to withdraw, and an active account."))}</p></article>` : "";
  body+=`<article class="card"><form class="admin-search" data-form="admin-search"><div class="field"><label for="user-search">${e(eligible?t("جست‌وجو در واجدین شرایط","Search eligible users"):t("جست‌وجو با نام کاربری، آیدی عددی یا کیف پول","Search by username, user ID or wallet"))}</label><input id="user-search" name="q" value="${e(state.userQuery||"")}" maxlength="100" placeholder="@username یا آیدی یا 0x…"></div><button class="btn primary" type="submit">${e(t("جست‌وجو","Search"))}</button></form><p class="switch-hint">${n(page.total)} ${e(eligible?t("کاربر واجد شرایط","eligible users"):t("حساب یافت شد","accounts found"))}</p><div class="user-cards">${page.users.length?page.users.map(adminUserCard).join(""):empty(t("کاربری پیدا نشد.","No users found."),"users")}</div><div class="account-actions"><button class="btn ghost" data-action="admin-users-page" data-page="${page.page-1}" ${page.page<=1?"disabled":""}>${e(t("قبلی","Previous"))}</button><span>${n(page.page)}</span><button class="btn ghost" data-action="admin-users-page" data-page="${page.page+1}" ${page.page*page.page_size>=page.total?"disabled":""}>${e(t("بعدی","Next"))}</button></div></article>`;
 } else if(tab==="audit") {
  body=`<article class="card"><div class="section-heading"><h2>${e(t("۵۰ عملیات اخیر مدیران","50 recent admin actions"))}</h2><a class="btn ghost small" href="/api/admin/export/audit" download>${e(t("خروجی کامل CSV","Export full CSV"))}</a></div>${a.audit.length?a.audit.map(row=>`<div class="admin-row"><div><h3>${e(adminActionLabel(row.action))}</h3><p>${e(t("مدیر ","Admin "))}${e(row.admin_id)} · ${e(t("شناسه ","Target "))}${e(row.target)}</p><p>${e(date(row.created_at,true))}</p>${row.details.reason?`<p>${e(row.details.reason)}</p>`:""}${row.details.amount?`<strong>${n(row.details.amount)} PRS</strong>`:""}</div></div>`).join(""):empty(t("هنوز عملیاتی ثبت نشده است.","No admin actions recorded yet."))}</article>`;
 } else {
  const s=a.stats,c=a.controls;
  body=`<div class="admin-stats">${[[a.users,t("کاربر ثبت‌شده","Registered users")],[s.active_mining,t("دوره فعال ماین","Active mining cycles")],[s.earned,t("کل پاداش ثبت‌شده PRS","Total rewards PRS")],[s.paid,t("پرداخت ثبت‌شده PRS","Payments recorded PRS")],[s.mining_spent,t("ماین دریافت‌شده PRS","Mining collected PRS")],[s.mining_reserved,t("رزرو دوره‌های ماین PRS","Reserved mining PRS")],[s.suspended,t("حساب تعلیق‌شده","Suspended accounts")],[Math.max(0,s.campaign_limit-s.earned-s.mining_reserved),t("ظرفیت باقی‌مانده PRS","Remaining campaign PRS")]].map(([value,label])=>`<article class="card admin-stat"><strong>${n(value)}</strong><span>${e(label)}</span></article>`).join("")}</div>${adminBurnCard(a.burn)}<div class="split-grid"><article class="card"><h2>${e(t("کنترل کمپین و ماین","Campaign & mining controls"))}</h2><form data-form="admin-controls"><div class="field account-section"><label for="campaign-state">${e(t("وضعیت پاداش‌های کمپین","Campaign rewards"))}</label><select id="campaign-state" name="paused"><option value="0" ${!c.paused?"selected":""}>${e(t("فعال","Active"))}</option><option value="1" ${c.paused?"selected":""}>${e(t("توقف موقت پاداش‌ها","Pause rewards"))}</option></select></div><div class="field"><label for="mining-state">${e(t("شروع دوره جدید ماین","New mining cycles"))}</label><select id="mining-state" name="mining_enabled"><option value="1" ${c.mining.enabled?"selected":""}>${e(t("فعال","Enabled"))}</option><option value="0" ${!c.mining.enabled?"selected":""}>${e(t("متوقف؛ دریافت دوره‌های قبلی مجاز","Paused; existing cycles can be collected"))}</option></select></div><div class="field"><label for="withdrawals-state">${e(t("درخواست برداشت کاربران","User withdrawal requests"))}</label><select id="withdrawals-state" name="withdrawals_enabled"><option value="1" ${c.withdrawals_enabled?"selected":""}>${e(t("فعال","Enabled"))}</option><option value="0" ${!c.withdrawals_enabled?"selected":""}>${e(t("غیرفعال","Disabled"))}</option></select></div><div class="field"><label for="mining-budget">${e(t("بودجه کل ماین PRS","Total mining budget PRS"))}</label><input id="mining-budget" type="number" name="mining_budget" min="${c.mining.spent+c.mining.reserved}" max="300000000" step="1" required value="${c.mining.budget}"><small>${e(t("این سقف شامل پاداش مصرف‌شده و دوره‌های رزروشده است.","This cap includes spent rewards and reserved cycles."))}</small></div><button class="btn primary" type="submit">${e(t("ذخیره تنظیمات","Save controls"))}</button></form></article><article class="card"><h2>${e(t("اطلاعیه داخل پنل","Portal announcement"))}</h2><form data-form="admin-announcement"><div class="field account-section"><label for="announcement">${e(t("متن اطلاعیه برای تمام کاربران؛ برای حذف خالی بگذار","Announcement for all users; leave empty to remove"))}</label><textarea id="announcement" name="announcement" maxlength="1500">${e(c.announcement)}</textarea></div><button class="btn primary" type="submit">${e(t("ثبت اطلاعیه","Save announcement"))}</button></form><div class="account-section"><h3>${e(t("گزارش‌ها","Reports"))}</h3><div class="account-actions"><a class="btn ghost" href="/api/admin/export-xlsx/paid" download>${e(t("اکسل پرداخت‌های موفق","Paid transactions Excel"))}</a><a class="btn ghost" href="/api/admin/export-xlsx/social" download>${e(t("اکسل شبکه‌های اجتماعی","Social profiles Excel"))}</a><a class="btn ghost" href="/api/admin/export/users" download>${e(t("گزارش کاربران CSV","Users CSV"))}</a></div><p class="switch-hint">${e(t("همه تاریخ‌ها و مهلت‌ها به وقت تهران هستند.","All dates and deadlines use Tehran time."))}</p></div></article></div><article class="card account-section"><h2>${e(t("۵۰ درخواست پرداخت اخیر","50 recent payment requests"))}</h2>${a.recent_payments.length?a.recent_payments.map(p=>`<div class="admin-row"><div><h3>${e(p.user_id)} · ${n(p.amount)} PRS</h3><p>${e(date(p.created_at,true))}</p></div>${statusBadge(p.status)}</div>`).join(""):empty(t("هنوز درخواستی نیست.","No payment requests yet."),"wallet")}</article>`;
 }
 return `${heading("PHASE 02 · MANAGEMENT",t("مدیریت ایردراپ","Airdrop management"),t("کاربران، بودجه، پاداش‌ها و سوابق را مدیریت کن.","Manage users, budgets, rewards and activity records."))}${tabs}${tab==="overview"?renderTelegramCheck():""}${body}`;
}
async function adminUserModal(uid) {
 const detail=await api(`/api/admin/users/${encodeURIComponent(uid)}`),u=detail.user;
 const status=u.suspended?t("تعلیق‌شده","Suspended"):u.registered?t("ثبت‌نام کامل","Registered"):t("ثبت‌نام ناقص","Incomplete");
 const payments=detail.payments;
 modal(t("مدیریت حساب ","Manage account ")+uid,`<div class="detail-line"><span>${e(t("وضعیت حساب","Account status"))}</span><strong>${e(status)}</strong></div><div class="detail-line"><span>${e(t("آیدی عددی تلگرام","Telegram numeric ID"))}</span><strong class="mono">${e(u.user_id)}</strong></div><div class="detail-line"><span>${e(t("نام کاربری تلگرام","Telegram username"))}</span><strong dir="ltr">${e(u.telegram_username||"—")}</strong></div><div class="detail-line"><span>${e(t("سطح","Level"))}</span><strong>${tierMark(u.level.id)} ${e(field(u.level,"name"))}</strong></div><div class="detail-line"><span>${e(t("دعوت‌ها / دعوت‌کننده","Referrals / inviter"))}</span><strong>${n(u.referrals)} / ${e(u.referred_by||"—")}</strong></div><div class="detail-line"><span>${e(t("کل پاداش / پرداخت‌شده / مانده","Earned / paid / balance"))}</span><strong>${n(u.earned)} / ${n(u.paid)} / ${n(u.unpaid)} PRS</strong></div><div class="detail-line"><span>${e(t("پاداش ماین دریافت‌شده","Mining rewards collected"))}</span><strong>${n(u.mining_total)} PRS</strong></div><div class="detail-line"><span>${e(t("وضعیت احراز / زبان","Verification / language"))}</span><strong>${e(u.verified)} · ${e(u.lang||"—")}</strong></div><div class="detail-line"><span>${e(t("تاریخ ثبت‌نام","Registered at"))}</span><strong>${u.registered_at?e(date(u.registered_at,true)):"—"}</strong></div><div class="detail-line"><span>${e(t("دریافت روزانه / پاداش‌ها","Daily count / bonuses"))}</span><strong>${n(u.daily_count)} · ${n(u.bonus_tokens)} / ${n(u.manual_bonus_tokens)} PRS</strong></div><div class="detail-line"><span>${e(t("واجد شرایط برداشت","Withdrawal eligible"))}</span><strong>${e(u.eligible?t("بله","Yes"):t("خیر","No"))}</strong></div><div class="detail-line"><span>${e(t("ثبت ولت در ربات","Wallet submitted in bot"))}</span><strong>${e(u.submitted?t("بله","Yes"):t("خیر","No"))}</strong></div><div class="detail-line"><span>${e(t("آزمون چالش","Challenge quiz"))}</span><strong>${n(u.challenge_quiz_attempts)} · ${e(u.challenge_quiz_passed?t("قبول","Passed"):t("قبول نشده","Not passed"))}</strong></div><div class="detail-line"><span>${e(t("ثبت / ویرایش شبکه‌های اجتماعی","Social registration / update"))}</span><strong>${u.social_registered_at?e(date(u.social_registered_at,true)):"—"} · ${u.social_updated_at?e(date(u.social_updated_at,true)):"—"}</strong></div><div class="detail-line"><span>${e(t("وضعیت ماین","Mining status"))}</span><strong>${e(detail.mining.enabled?t("فعال","Enabled"):t("غیرفعال","Disabled"))}${detail.mining.cycle?` · ${e(t("فعال تا ","Active until "))}${e(date(detail.mining.cycle.ends_at,true))} · ${n(detail.mining.cycle.reward)} PRS`:""}</strong></div><h3 class="account-section">${e(t("آدرس کیف پول ثبت‌شده","Registered wallet address"))}</h3><p class="evidence mono" dir="ltr">${e(u.wallet||t("ثبت نشده","Not registered"))}</p><div class="user-card-actions">${adminPayBlock(u)}</div><div class="detail-line"><span>Instagram</span><strong>${socialLink(u.instagram,"instagram")}</strong></div><div class="detail-line"><span>X / Twitter</span><strong>${socialLink(u.twitter,"twitter")}</strong></div><form data-form="admin-user-action" data-id="${e(uid)}" data-request-id="${crypto.randomUUID()}"><div class="field"><label for="user-action">${e(t("عملیات","Action"))}</label><select id="user-action" name="action"><option value="bonus">${e(t("ثبت پاداش دستی","Record manual reward"))}</option><option value="unlock_wallet">${e(t("اجازه یک اصلاح کیف پول","Allow one wallet edit"))}</option><option value="${u.suspended?"resume":"suspend"}">${e(u.suspended?t("رفع تعلیق","Restore account"):t("تعلیق حساب","Suspend account"))}</option></select></div><div class="field"><label for="user-bonus">${e(t("مبلغ؛ فقط برای پاداش دستی PRS","Amount; manual reward only PRS"))}</label><input id="user-bonus" name="amount" type="number" min="1" max="300000000" step="1"></div><div class="field"><label for="user-reason">${e(t("دلیل عملیات؛ در سابقه ثبت می‌شود","Reason; saved in the audit history"))}</label><textarea id="user-reason" name="reason" minlength="3" maxlength="400" required></textarea></div><button class="btn primary full" type="submit">${e(t("ثبت عملیات","Apply action"))}</button></form><details class="account-section"><summary>${e(t("اصلاح کیف پول توسط مدیر","Admin wallet correction"))}</summary><form data-form="admin-wallet" data-id="${e(uid)}"><div class="field"><label for="admin-wallet">${e(t("آدرس عمومی BNB","BNB public address"))}</label><input id="admin-wallet" class="wallet-input" name="wallet" value="${e(u.wallet)}" pattern="0x[a-fA-F0-9]{40}" maxlength="42" required></div><button class="btn ghost" type="submit">${e(t("ذخیره آدرس","Save address"))}</button></form></details><details class="account-section"><summary>${e(t("دعوت‌های مرتبط","Linked referrals"))} (${n(detail.referrals.length)})</summary>${u.referral_quality&&u.referral_quality.invited?`<p class="${u.referral_quality.inactive_percent>=50?"notice red":"notice"}">${e(t(`${n(u.referral_quality.inactive)} نفر از ${n(u.referral_quality.invited)} دعوت (${n(u.referral_quality.inactive_percent)}٪) هیچ پاداش روزانه‌ای نگرفته و کیف پول ثبت نکرده‌اند. درصد بالا نشانه احتمالی اکانت فیک است.`,`${u.referral_quality.inactive} of ${u.referral_quality.invited} invitees (${u.referral_quality.inactive_percent}%) never claimed a daily reward or saved a wallet. A high share can indicate fake accounts.`))}</p>`:""}${detail.referrals.map(r=>`<p class="detail-line">${e(r.user_id)} · ${e(r.telegram_username||"—")} · ${e(r.registered?t("ثبت‌نام کامل","Registered"):t("ثبت‌نام ناقص","Incomplete"))}${r.active===false?` · ${e(t("خارج‌شده از کانال","Left the channel"))}`:""}</p>`).join("")}</details><details class="account-section"><summary>${e(t("وضعیت مأموریت‌ها","Mission activity"))} (${n(detail.submissions.length)})</summary>${detail.submissions.length?detail.submissions.map(item=>`<p class="detail-line">${e(item.mission_id||"—")} · ${e(item.status||"—")} · ${n(item.reward||0)} PRS · ${e(date(item.created_at,true))}</p>`).join(""):empty(t("سابقه مأموریتی ثبت نشده است.","No mission history recorded."))}</details><details class="account-section"><summary>${e(t("پرداخت‌های اخیر","Recent payments"))} (${n(detail.payments.length)})</summary>${payments.length?payments.map(p=>`<div class="payment-item"><strong>${n(p.amount)} PRS · ${e(p.status)}</strong><p class="mono" dir="ltr">${e(p.tx_hash||"—")}</p></div>`).join(""):empty(t("پرداختی ثبت نشده است.","No payments recorded."))}</details><h3 class="account-section">${e(t("فعالیت‌های اخیر","Recent activity"))}</h3>${historyList(detail.history.slice(0,100))}`);
}
function payBlockReason(u){if(u.suspended)return t("حساب تعلیق است","Account suspended");if(!/^0x[0-9a-fA-F]{40}$/.test(u.wallet||""))return t("کیف پول ثبت نشده","No wallet saved");if(u.referrals<3)return t("کمتر از ۳ دعوت","Fewer than 3 referrals");if(u.unpaid<20000)return t("مانده کمتر از ۲۰٬۰۰۰ PRS","Balance under 20,000 PRS");return t("واجد شرایط پرداخت نیست","Not eligible for payment");}
function cancelPaymentButton(paymentId,uid){return `<button class="btn ghost small" data-action="admin-cancel-payment" data-payment="${e(paymentId)}" data-id="${e(uid)}">${e(t("لغو درخواست وجه","Cancel payment request"))}</button>`;}
function adminPayBlock(u){const op=u.open_payment;if(op&&op.status==="sending")return `<span class="badge gold">${e(t("در حال تأیید تراکنش","Confirming transaction"))}</span>`;if(op&&op.status==="signing")return `<span class="badge gold">${e(t("در حال امضا در Trust Wallet","Being signed in Trust Wallet"))}</span>${cancelPaymentButton(op.id,u.user_id)}`;if(u.eligible||op?.status==="pending"){const amount=op?.amount||u.unpaid;return `<button class="btn primary small" data-action="admin-pay-user" data-id="${e(u.user_id)}" data-amount="${e(amount)}">${e(t("پرداخت توکن","Pay tokens"))} · ${n(splitBurn(amount)[0])} PRS</button>${op?.status==="pending"?cancelPaymentButton(op.id,u.user_id):""}`;}return `<small class="muted">${e(payBlockReason(u))}</small>`;}
function adminUserCard(u){const status=u.suspended?["red",t("تعلیق","Suspended")]:u.registered?["green",t("ثبت‌نام کامل","Registered")]:["",t("ثبت‌نام ناقص","Incomplete")];return `<div class="user-card"><div class="user-card-head"><div><strong class="mono">${e(u.user_id)}</strong><small dir="ltr">${e(u.telegram_username||"—")}</small></div><span class="badge ${status[0]}">${e(status[1])}</span></div><div class="user-card-amounts"><div><small>${e(t("کسب‌شده","Earned"))}</small><strong class="number">${n(u.earned)}</strong></div><div><small>${e(t("پرداخت‌شده","Paid"))}</small><strong class="number">${n(u.paid)}</strong></div><div><small>${e(t("مانده","Balance"))}</small><strong class="number">${n(u.unpaid)}</strong></div></div><div class="detail-line"><span>${e(t("کیف پول BNB","BNB wallet"))}</span></div><p class="user-card-wallet mono" dir="ltr">${e(u.wallet||"—")}</p><div class="detail-line"><span>Instagram</span><strong>${socialLink(u.instagram,"instagram")}</strong></div><div class="detail-line"><span>X / Twitter</span><strong>${socialLink(u.twitter,"twitter")}</strong></div><div class="detail-line"><span>${e(t("دعوت / معرف","Referrals / inviter"))}</span><strong>${n(u.referrals)} / ${e(u.referred_by||"—")}</strong></div><div class="detail-line"><span>${e(t("سطح","Level"))}</span><strong>${tierMark(u.level.id)} ${e(field(u.level,"name"))}</strong></div><div class="detail-line"><span>${e(t("سهم توکن‌سوزی","Burn share"))}</span><strong>${n(u.burn_share||0)} PRS</strong></div>${u.open_payment?`<p class="switch-hint">${e(t("درخواست وجه باز","Open payment request"))}: ${n(u.open_payment.amount)} PRS · ${e(paymentStatusText(u.open_payment.status))}</p>`:""}<div class="user-card-actions"><button class="btn ghost small" data-action="admin-user" data-id="${e(u.user_id)}">${e(t("همه اطلاعات","Full details"))}</button>${adminPayBlock(u)}</div></div>`;}
async function walletPayoutLoop(ids){if(!window.prsWalletConnector)await import("/static/wallet-payout.js?v=20261020-tw-inapp-1");if(!window.prsWalletConnector)throw Object.assign(new Error("wallet_module_missing"),{code:"wallet_module_missing"});const wallet=await window.prsWalletConnector.connect();let paid=0;for(const id of ids){const prepared=await api("/api/admin/payments/prepare-wallet-payout","POST",{payment_id:id});if(prepared.payout_wallet.toLowerCase()!==wallet.address.toLowerCase()){await api(`/api/admin/payments/${encodeURIComponent(id)}/cancel-wallet-payout`,"POST",{not_sent:true});throw Object.assign(new Error("wrong_wallet"),{code:"wrong_wallet"});}if(!confirm(t(`ارسال ${n(prepared.amount)} PRS به آدرس ${prepared.recipient} از کیف پول ${prepared.payout_wallet}؟`,`Send ${n(prepared.amount)} PRS to ${prepared.recipient} from treasury wallet ${prepared.payout_wallet}?`))){await api(`/api/admin/payments/${encodeURIComponent(id)}/cancel-wallet-payout`,"POST",{not_sent:true});break;}let hash;try{hash=await window.prsWalletConnector.send(prepared.transaction);}catch(error){if(Number(error.code)===4001){await api(`/api/admin/payments/${encodeURIComponent(id)}/cancel-wallet-payout`,"POST",{not_sent:true});}throw error;}rememberPayoutHash(id,hash);await api(`/api/admin/payments/${encodeURIComponent(id)}/confirm-wallet-payout`,"POST",{tx_hash:hash});forgetPayoutHash(id);paid++;}return paid;}
function adminPayUser(button){const uid=button.dataset.id,amount=Number(button.dataset.amount||0);const [net,burn]=splitBurn(amount);if(!confirm(t(`پرداخت ${n(net)} PRS به کاربر ${uid} با Trust Wallet؟ (${n(burn)} PRS سهم توکن‌سوزی کسر می‌شود.) قبل از امضا، مبلغ و آدرس دوباره نشان داده می‌شود.`,`Pay ${n(net)} PRS to user ${uid} with Trust Wallet? (${n(burn)} PRS burn share is kept.) The amount and address are shown again before signing.`)))return;busy(button,async()=>{const started=await api(`/api/admin/users/${encodeURIComponent(uid)}/payment`,"POST",{});const paid=await walletPayoutLoop([started.payment.id]);if($("modal").open)closeModal();if(state.userPage)state.userPage=await api(adminUsersPath(state.userPage.page||1));state.admin=await api("/api/admin/overview");render();toast(paid?t("پرداخت روی بلاکچین تأیید و ثبت شد.","The payout was confirmed and recorded on-chain."):t("پرداخت انجام نشد؛ درخواست در بخش «مأموریت و درخواست‌ها» در انتظار ماند.","Not paid; the request is waiting under Missions & requests."));});}
function paymentStatusText(status){return ({pending:t("در انتظار پرداخت","Waiting for payout"),signing:t("در حال امضا","Being signed"),sending:t("در حال تأیید تراکنش","Confirming transaction"),recorded:t("پرداخت شد","Paid"),rejected:t("لغو شد","Cancelled")})[status]||status;}
function adminCancelPayment(button){const pid=button.dataset.payment;const reason=prompt(t("دلیل لغو درخواست وجه (به کاربر نشان داده می‌شود):","Reason for cancelling (shown to the user):"),t("لغو درخواست توسط مدیریت","Cancelled by the administrator"));if(reason===null)return;if(reason.trim().length<3){toast(t("دلیل لغو را بنویس.","Write a reason."),true);return;}busy(button,async()=>{let result;try{result=await api(`/api/admin/payments/${encodeURIComponent(pid)}/cancel`,"POST",{reason:reason.trim()});}catch(error){if(error.code!=="payout_check_too_old")throw error;if(!confirm(t("این تلاش پرداخت قدیمی است و سایت نمی‌تواند خودکار روی شبکه جستجو کند. در BscScan، تراکنش‌های کیف پول خزانه به آدرس همین کاربر را بررسی کن. فقط اگر هیچ انتقالی نبود، تأیید کن.","This payout attempt is too old to search automatically. On BscScan, check the treasury wallet for transfers to this user. Confirm only if there is none.")))return;result=await api(`/api/admin/payments/${encodeURIComponent(pid)}/cancel`,"POST",{reason:reason.trim(),force:true});}forgetPayoutHash(pid);if($("modal").open)closeModal();if(state.userPage)state.userPage=await api(adminUsersPath(state.userPage.page||1));state.admin=await api("/api/admin/overview");render();toast(result.recovered?t("این پرداخت قبلاً روی بلاکچین انجام شده بود؛ به‌عنوان پرداخت‌شده ثبت شد و لغو نشد.","This payout had already been sent on-chain. It was recorded as paid, not cancelled."):t("درخواست وجه لغو شد. کاربر دلیل را در حسابش می‌بیند و می‌تواند دوباره درخواست بدهد.","Payment request cancelled. The user sees the reason and can request again."));});}
function adminUsersPath(page=1) {const eligible=state.adminTab==="eligible";return `/api/admin/users?${eligible?"eligible=1&":""}q=${encodeURIComponent(state.userQuery||"")}&page=${page}`;}
function phaseTwoClick(button) {
 const action=button.dataset.action;
 if(action==="admin-pay-user"){adminPayUser(button);return true;}
 if(action==="admin-cancel-payment"){adminCancelPayment(button);return true;}
 if(action==="admin-tab"){state.adminTab=button.dataset.tab;state.userQuery="";if(["users","eligible"].includes(state.adminTab)){busy(button,async()=>{state.userPage=await api(adminUsersPath(1));render();});}else render();return true;}
 if(action==="archive-mission"){archiveMissionModal(button.dataset.id);return true;}
 if(!["mining-start","mining-claim","admin-user","admin-users-page","restore-mission","telegram-check"].includes(action))return false;
 busy(button,async()=>{
  if(action==="mining-start"){await api("/api/mining/start","POST");await refresh();toast(t("دوره ۸ساعته شروع شد.","Your 8-hour cycle has started."));}
  else if(action==="mining-claim"){const result=await api("/api/mining/claim","POST",{cycle_id:state.me.mining.cycle.id});await refresh();if(!result.already_claimed)celebrateHeritageReward(result.amount);toast(t(`${n(result.amount)} PRS به حسابت اضافه شد.`,`${n(result.amount)} PRS added to your balance.`));}
  else if(action==="restore-mission"){await api(`/api/admin/missions/${encodeURIComponent(button.dataset.id)}/archive`,"POST",{archived:false});await refresh();toast(t("مأموریت بازگردانده شد؛ برای شروع آن را فعال کن.","Mission restored. Activate it when ready."));}
  else if(action==="telegram-check"){state.telegramCheck=await api("/api/admin/telegram/check","POST",{});render();}
  else if(action==="admin-user")await adminUserModal(button.dataset.id);
  else {state.userPage=await api(adminUsersPath(Number(button.dataset.page)));render();}
 });
 return true;
}
function handlePhaseTwoForm(form,submitter,fd) {
 const kind=form.dataset.form;
 if(!["admin-search","admin-controls","admin-announcement","admin-user-action","admin-wallet","archive-mission"].includes(kind))return false;
 busy(submitter,async()=>{
  if(kind==="admin-search"){state.userQuery=String(fd.get("q")||"");state.userPage=await api(adminUsersPath(1));render();return;}
  if(kind==="archive-mission"){await api(`/api/admin/missions/${encodeURIComponent(form.dataset.id)}/archive`,"POST",{archived:true});closeModal();toast(t("مأموریت از فهرست حذف شد؛ سوابق و پاداش‌ها محفوظ است.","Mission removed from the list. Rewards and history are preserved."));}
  else if(kind==="admin-controls")await api("/api/admin/controls","POST",{paused:fd.get("paused")==="1",mining_enabled:fd.get("mining_enabled")==="1",withdrawals_enabled:fd.get("withdrawals_enabled")==="1",mining_budget:Number(fd.get("mining_budget"))});
  else if(kind==="admin-announcement")await api("/api/admin/controls","POST",{announcement:fd.get("announcement")});
  else if(kind==="admin-wallet"){await api(`/api/admin/users/${encodeURIComponent(form.dataset.id)}/wallet`,"POST",{wallet:fd.get("wallet")});closeModal();}
  else {await api(`/api/admin/users/${encodeURIComponent(form.dataset.id)}/action`,"POST",{action:fd.get("action"),amount:Number(fd.get("amount")),reason:fd.get("reason"),request_id:form.dataset.requestId});closeModal();}
  if(state.userPage)state.userPage=await api(adminUsersPath(state.userPage.page));
  await refresh();toast(t("تغییرات ثبت شد.","Changes saved."));
 });
 return true;
}
setInterval(()=>{if(!document.hidden)updatePhaseTwoClocks();},1000);

// PRS Heritage theme: presentation only; existing API and account rules stay in place.
const heritageMotionQuery = typeof window.matchMedia === "function"
  ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
let heritageMotionEnabled = true;
let heritageRewardTimer;
try { heritageMotionEnabled = localStorage.getItem("prs-motion") !== "off"; } catch (_) {}

function heritageAllowsMotion() {
  return heritageMotionEnabled && !heritageMotionQuery?.matches && !document.hidden;
}

function syncThemeMotion() {
  const active = heritageAllowsMotion();
  document.documentElement.dataset.motion = active ? "on" : "off";
  document.querySelectorAll(".motion-toggle").forEach(button => {
    button.setAttribute("aria-pressed", String(active));
    button.setAttribute("aria-label", t("حرکت‌های تزئینی", "Decorative motion"));
    button.title = heritageMotionQuery?.matches
      ? t("حرکت‌ها طبق تنظیم کاهش حرکت دستگاه خاموش‌اند", "Motion follows your device's reduced-motion setting")
      : active ? t("توقف حرکت‌های تزئینی", "Pause decorative motion")
        : t("فعال‌کردن حرکت‌های تزئینی", "Enable decorative motion");
    button.disabled = Boolean(heritageMotionQuery?.matches);
    button.innerHTML = active
      ? '<svg viewBox="0 0 24 24" class="icon" aria-hidden="true"><path d="M9 5v14M15 5v14"/></svg>'
      : '<svg viewBox="0 0 24 24" class="icon" aria-hidden="true"><path d="m9 5 10 7-10 7V5Z"/></svg>';
  });
  if (!active) clearHeritageReward();
}

function heritageBanner() {
  const label = t("تصویر هنری آرامگاه کوروش با سرستون‌های تخت جمشید و نقش سربازان هخامنشی",
    "Artistic tribute to the Tomb of Cyrus, Persepolis capitals and Achaemenid guards");
  return '<section class="heritage-hero" aria-label="' + e(t("میراث PRS", "The PRS heritage")) + '">' +
    '<div class="heritage-copy"><div class="heritage-kicker"><span class="heritage-spark" aria-hidden="true">✦</span>' +
    '<span>PRS · PERSEPOLIS</span></div><h2>' + e(t("از ریشه‌های بزرگ،\nبه فردایی مشترک.", "A timeless heritage.\nA shared tomorrow.")) + '</h2>' +
    '<p>' + e(t("مأموریت امروزت را انتخاب کن و به ساختن جامعه PRS کمک کن.", "Choose your next mission and help build the PRS community.")) + '</p>' +
    '<button class="btn primary" type="button" data-action="navigate" data-route="missions">' +
    icon("target") + e(t("کشف مأموریت‌ها", "Explore missions")) + icon("arrow") + '</button>' +
    '<div class="heritage-caption"><span></span>PASARGADAE · PERSEPOLIS</div></div>' +
    '<div class="heritage-art" role="img" aria-label="' + e(label) + '">' +
    '<span class="heritage-dust dust-one" aria-hidden="true">✦</span><span class="heritage-dust dust-two" aria-hidden="true">✧</span>' +
    '<span class="heritage-dust dust-three" aria-hidden="true">✦</span></div></section>';
}

function decorateHeritageRoute() {
  const page = $("page");
  page.dataset.route = state.route;
  if (state.route !== "dashboard") return;
  page.querySelector(".page-title")?.insertAdjacentHTML("afterend", heritageBanner());
  const watermark = page.querySelector(".hero-watermark");
  if (watermark) watermark.innerHTML = '<img src="/static/mark.svg" width="76" height="76" alt="">';
  const dailyIcon = page.querySelector(".daily-card .card-top .icon-tile");
  if (dailyIcon) dailyIcon.innerHTML = '<span class="heritage-gift" aria-hidden="true">🎁</span>';
}

function clearHeritageReward() {
  clearTimeout(heritageRewardTimer);
  $("heritage-reward")?.remove();
}

function celebrateHeritageReward(amount) {
  clearHeritageReward();
  const value = Number(amount);
  if (!heritageAllowsMotion() || !Number.isFinite(value) || value <= 0) return;
  const layer = document.createElement("div");
  layer.id = "heritage-reward";
  layer.className = "heritage-reward";
  layer.setAttribute("aria-hidden", "true");
  for (let i = 0; i < 12; i++) {
    const particle = document.createElement("span");
    particle.className = "reward-particle";
    if (i % 3 === 0) {
      const coin = document.createElement("img");
      coin.src = "/static/mark.svg";
      coin.alt = "";
      coin.width = coin.height = 26;
      particle.append(coin);
    } else particle.textContent = i % 2 ? "✦" : "✧";
    layer.append(particle);
  }
  const medallion = document.createElement("div");
  medallion.className = "reward-medallion";
  const logo = document.createElement("img");
  logo.src = "/static/mark.svg";
  logo.alt = "";
  logo.width = logo.height = 84;
  const label = document.createElement("strong");
  label.textContent = "+" + n(value) + " PRS";
  medallion.append(logo, label);
  layer.append(medallion);
  document.body.append(layer);
  heritageRewardTimer = setTimeout(clearHeritageReward, 2200);
}

function initHeritageTheme() {
  document.documentElement.dataset.heritage = "prs-2026";
  const themeMeta = document.querySelector('meta[name="theme-color"]');
  if (themeMeta) themeMeta.content = "#090909";
  document.querySelectorAll(".brand-mark").forEach(mark => {
    const image = document.createElement("img");
    image.src = "/static/mark.svg";
    image.alt = "";
    image.width = image.height = 56;
    mark.replaceChildren(image);
  });
  const orbit = document.querySelector(".login-orbit");
  if (orbit) {
    orbit.className = "heritage-plaque";
    orbit.innerHTML = '<span class="heritage-plaque-line"></span><span>PASARGADAE · PERSEPOLIS</span><span class="heritage-plaque-line"></span>';
  }
  const eyebrow = document.querySelector(".login-story-copy .eyebrow");
  if (eyebrow) eyebrow.textContent = "A CULTURE. A COMMUNITY. A SHARED FUTURE.";
  const story = document.querySelector(".login-story");
  if (story) {
    const sparks = document.createElement("div");
    sparks.className = "heritage-atmosphere";
    sparks.setAttribute("aria-hidden", "true");
    sparks.innerHTML = '<span>✦</span><span>✧</span><span>✦</span><span>✧</span>';
    story.append(sparks);
  }
  const context = document.querySelector(".topbar-context");
  if (context) {
    const brand = document.createElement("a");
    brand.className = "header-brand";
    brand.href = "#dashboard";
    brand.setAttribute("aria-label", "PRS");
    brand.innerHTML = '<img src="/static/mark.svg" width="42" height="42" alt="">';
    context.prepend(brand);
  }
  [document.querySelector(".login-form-wrap"), document.querySelector(".topbar-actions")].forEach(parent => {
    if (!parent) return;
    const button = document.createElement("button");
    button.type = "button";
    button.className = "motion-toggle";
    button.addEventListener("click", () => {
      heritageMotionEnabled = !heritageMotionEnabled;
      try { localStorage.setItem("prs-motion", heritageMotionEnabled ? "on" : "off"); } catch (_) {}
      syncThemeMotion();
    });
    parent.prepend(button);
  });
  heritageMotionQuery?.addEventListener?.("change", syncThemeMotion);
  document.addEventListener("visibilitychange", syncThemeMotion);
  window.addEventListener("pagehide", clearHeritageReward);
  syncThemeMotion();
}

initHeritageTheme();
init();
